from itertools import product

def peluang_jumlah_syarat(k, syarat):
    S = [h for h in product(range(1, 7), repeat=2) if syarat(*h)]
    if not S:
        return 0.0
    return round(sum(1 for a, b in S if a + b == k) / len(S), 4)

