    # TODO: implementasikan
    pass

exercises.solution:
def posterior_berurutan(prev, sens, spes, n):
    p = prev
    for _ in range(n):
        p = p * sens / (p * sens + (1 - p) * (1 - spes))
    return round(p, 4)

